@Transactional
public void enroll() {
    Student2 s = entityManager.find(Student2.class, 1L);
    Course c = entityManager.find(Course.class, 101L);
    c.getStudents().add(s);
}

@Entity
class Profile {
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    private String bio;

    @OneToOne
    @MapsId
    @JoinColumn(name = "id")
    private User user;
}
